import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.codec.binary.Base64.isArrayByteBase64
 */
public class Base64_isArrayByteBase64_TriageGen2Test {







    @Test
    public void testIsArrayByteBase64_InvalidCharacters() {
        // '!' is not a Base64 character and not whitespace
        byte[] input = "SGVsbG8h".getBytes();
        assertFalse("Bytes containing non-base64 and non-whitespace characters should return false", 
            Base64.isArrayByteBase64(input));
    }






}

